#pragma once
#include "qualification_mailbox.h"
namespace xllama::qualification {
inline std::string quoted(const std::string&s){return first_answer::quote(s);}
inline std::string prework_fields(const Session&s){const auto n=s.last_clock;const bool steady=s.clock_sampled&&s.clock.first.steady&&n.steady>=s.clock.first.steady;return "\"prework_mask\":"+std::to_string(s.prework_mask)+",\"prework_detail\":"+quoted(s.prework_detail)+",\"device_utc_available\":"+(n.utc?"true":"false")+",\"device_utc_ms\":"+(n.utc?std::to_string(n.utc):std::string("null"))+",\"steady_elapsed_ms\":"+(steady?std::to_string(n.steady-s.clock.first.steady):std::string("null"));}
inline std::string quota_fields(const Session&s){const auto&q=s.quota;return "\"quota_available_mask\":"+std::to_string(q.available)+",\"quota_first_limit\":"+((q.available&1)?std::to_string(q.first):std::string("null"))+",\"quota_current_limit\":"+((q.available&8)?std::to_string(q.current):std::string("null"))+",\"quota_usage\":"+((q.available&2)?std::to_string(q.usage):std::string("null"))+",\"quota_level\":"+((q.available&4)?std::to_string(q.level):std::string("null"))+",\"quota_bracket_initial_limit\":"+(q.bracket_first?std::to_string(q.bracket_first):std::string("null"));}
inline std::string base_fields(const Session&s){const auto&p=s.selected;return "\"run_id\":"+quoted(p.run)+",\"selection_id\":"+quoted(p.selection)+",\"full_package_name\":"+quoted(s.actual_package)+",\"requested_full_package_name\":"+quoted(s.requested_package)+",\"signed_artifact_sha256\":"+quoted(p.artifact_sha)+",\"instance_id\":"+quoted(s.instance)+",\"nonce_sha256\":"+quoted(s.nonce)+",\"prepare_sha256\":"+quoted(s.prepare_sha)+",\"stage\":"+quoted(name(p.work));}
inline std::string control_body(const Session&s,uint32_t pid,const std::string&phase,const std::string&command_sha,const std::string&completion_nonce,uint32_t stop_mask,const std::string&detail){
 return "{\"schema\":\"xllama-qualification-receipt-v1\","+base_fields(s)+","+prework_fields(s)+","+quota_fields(s)+",\"phase\":"+quoted(phase)+",\"ready_sha256\":"+quoted(s.ready_sha)+",\"command_sha256\":"+quoted(command_sha)+",\"completion_nonce_sha256\":"+quoted(completion_nonce)+",\"pid\":"+std::to_string(pid)+",\"detail\":"+quoted(bounded_detail(detail))+",\"additional_stop_mask\":"+std::to_string(stop_mask)+",\"stage_reason_status\":\"SEE_NATIVE_REASON_OR_UNAVAILABLE\",\"native_resources_closed\":null,\"normal\":false,\"acceptance\":\"NOT_GRANTED\",\"external_issuer_verified\":false}";
}
inline std::string ready_body(const Session&s,uint32_t pid,bool stage_handlers=true){return "{\"schema\":\"xllama-qualification-ready-v1\","+base_fields(s)+","+prework_fields(s)+","+quota_fields(s)+",\"phase\":1,\"mode\":"+quoted(s.state==Phase::ready?"diagnostic":"manual")+",\"pid\":"+std::to_string(pid)+",\"issued_at_epoch_ms\":"+std::to_string(s.clock.first.utc)+",\"expires_at_epoch_ms\":"+std::to_string(s.clock.expiry)+",\"ready_wait_ms\":120000,\"retained_charge_bytes\":"+std::to_string(retained_charge)+",\"critical_receipt_cap\":16384,\"model_opened\":false,\"stage_started\":false,\"native_authenticates_external_issuer\":false,\"activation_origin_verified\":false,\"runtime_owner\":null,\"compiled_stage_handlers\":"+(stage_handlers?std::string("[\"identity\",\"proof_primitive16\",\"proof_model2_v1_v4\",\"cpu_dev\",\"generation_explicit_permit\"]"):std::string("[]"))+"}";}
}
